import{_t as e,it as t,n,rt as r}from"./chunks/framework.yS8CksER.js";var i=JSON.parse(`{"title":"Was OEA ist","description":"","frontmatter":{"title":"Was OEA ist","covers":{"screens":[],"stories":[]}},"headers":[],"relativePath":"de/introduction/index.md","filePath":"de/introduction/index.md"}`),a={name:`de/introduction/index.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="was-oea-ist" tabindex="-1">Was OEA ist <a class="header-anchor" href="#was-oea-ist" aria-label="Permalink to “Was OEA ist”">​</a></h1><p>OEA – Open Enterprise Architecture – ist ein Open-Source-Werkzeug für das Enterprise Architecture Management. Damit erfasst du die Bestandteile der Architektur deiner Organisation (Anwendungen, Daten, Technologie), beschreibst sie mit den Eigenschaften, die deine Organisation braucht, und betrachtest sie in Tabellen und später in Diagrammen und Dashboards.</p><h2 id="editionen" tabindex="-1">Editionen <a class="header-anchor" href="#editionen" aria-label="Permalink to “Editionen”">​</a></h2><ul><li><strong>Community Edition</strong>: Open Source unter der GNU Affero General Public License 3.0 (AGPL-3.0)</li><li><strong>Enterprise Edition</strong>: derselbe Kern mit zusätzlichen Funktionen unter einer proprietären Lizenz</li></ul><p>Dieses Handbuch beschreibt die Community Edition.</p><h2 id="begriffe" tabindex="-1">Begriffe <a class="header-anchor" href="#begriffe" aria-label="Permalink to “Begriffe”">​</a></h2><p><strong>Metamodell</strong> : Die Arten von Dingen, die dein Repository enthält (<em>Entitätstypen</em>, zum Beispiel <em>Application Component</em> oder <em>Data Object</em>), und ihre Eigenschaften. Eine neue Instanz startet ohne Entitätstypen; du importierst ein Starterpaket oder ein eigenes Metamodell-Paket.</p><p><strong>Entität</strong> : Ein Element der Architektur, zum Beispiel die Anwendung <em>CRM System</em>. Jede Entität gehört zu einem Entitätstyp und trägt Werte für dessen Eigenschaften. Jede Änderung erzeugt eine neue Version.</p><p><strong>Katalog</strong> : Eine wiederverwendbare Tabellenansicht des Repositorys. Ein Katalog zeigt die Entitäten eines Entitätstyps als Zeilen; du sortierst und blätterst durch sie.</p><p><strong>Rollen und Berechtigungen</strong> : Was eine Person tun darf, hängt von den Berechtigungen ihrer Rollen ab. Rollen werden über die Gruppen deines Identity-Providers vergeben.</p><h2 id="was-die-aktuelle-version-bietet" tabindex="-1">Was die aktuelle Version bietet <a class="header-anchor" href="#was-die-aktuelle-version-bietet" aria-label="Permalink to “Was die aktuelle Version bietet”">​</a></h2><p>Dieses Handbuch beschreibt den Entwicklungsstand von OEA. Es enthält die Funktionen, die implementiert sind:</p><ul><li>eine Instanz installieren und ihren ersten Administrator einrichten</li><li>einen Identity-Provider (OpenID Connect) anbinden und Rollen über seine Gruppen vergeben</li><li>die Starterkonfiguration und Metamodell-Pakete importieren</li><li>dich über den Identity-Provider oder mit dem lokalen Systemadmin-Konto anmelden, mit zweitem Faktor</li><li>Kataloge anlegen und ihre Entitäten ansehen</li><li>Entitäten im Batch über die API schreiben</li></ul><div class="info custom-block"><p class="custom-block-title">Weboberfläche</p><p>In diesem Entwicklungsstand läuft die Weboberfläche in der Entwicklungsumgebung des Repositorys (<code>scripts/dev.sh</code>, siehe den <a href="https://github.com/open-enterprise-architecture/OEA/blob/main/docs/development.md" target="_blank" rel="noreferrer">Development Guide</a>). Das Betreiber-Setup aus <a href="./../setup/installation">Installation</a> stellt die API bereit; alle Funktionen dieses Handbuchs stehen auch über die <a href="./../api/">API</a> zur Verfügung.</p><p>Die Screenshots dieses Handbuchs entstehen automatisch in dieser Umgebung mit ihren Beispieldaten (Instanz <code>acme</code>, Benutzer des Entwicklungs-Realms).</p></div>`,14)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};